import{_ as a,c as n,b as l,o as i}from"./app-cFKR3TmS.js";const s={};function t(d,e){return i(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="项目" tabindex="-1"><a class="header-anchor" href="#项目"><span>项目</span></a></h1><h2 id="项目一描述" tabindex="-1"><a class="header-anchor" href="#项目一描述"><span>项目一描述</span></a></h2><p>一个工业 PLC 编程的 梯形图（LD）和功能块图（FBD）图形化编辑工具 ，用于以拖拽方式替代传统文本化的 PLC 编程。</p><h3 id="技术栈" tabindex="-1"><a class="header-anchor" href="#技术栈"><span>技术栈</span></a></h3><p>Vue 2 (^2.6.14) + Vuex 3 + Composition API</p><p>AntV X6 (^2.9.4) — 核心画布引擎</p><p>Element UI 2</p><p>webpack</p><h3 id="项目结构" tabindex="-1"><a class="header-anchor" href="#项目结构"><span>项目结构</span></a></h3><p>ldfbd/ ├── src/ │ ├── index.js # 组件库入口（Vue 插件） │ ├── ld.js # 梯形图模式入口 │ ├── fbd.js # 功能块图模式入口 │ ├── src/ │ │ ├── LD.vue / FBD.vue # 两种模式的容器组件 │ │ ├── ladderArea.vue # ⭐ 核心编辑画布（213KB+，核心组件） │ │ ├── components/ # 子组件（工具栏、功能块节点、变量管理等） │ │ ├── store/modules/ # Vuex 状态（主要管理 cells 数据） │ │ ├── utils/ # 工具函数（20+ 个文件：坐标、连线、删除、撤销等） │ │ ├── dataJson/ # 功能块元数据 JSON（按 LD/FBD 分类，各 11 类） │ │ └── api/ld.js # 后端 API 接口 │ ├── assets/ │ │ ├── images/ # 梯形图元件图片（触点、线圈、定时器等） │ │ └── svg/ # 图标 │ └── index.html ├── webpack.config.js # Webpack 构建配置（UMD 库打包） └── vue.config.js # Vue CLI 后备配置</p><h3 id="核心功能" tabindex="-1"><a class="header-anchor" href="#核心功能"><span>核心功能</span></a></h3><ol><li>梯形图（LD）编辑 — 拖拽触点、线圈、功能块到画布，图形化编写 PLC 逻辑</li><li>功能块图（FBD）编辑 — 使用功能块节点进行图形化编程</li><li>编辑交互 — 撤销/重做、缩放、全屏、导入/导出、添加节/行</li><li>变量管理 — 全局/局部变量的选择、新建、列表查看</li><li>后端集成 — 通过 REST API（端口 9999）实现加载、保存、编译、运行监控</li></ol><h4 id="数据流" tabindex="-1"><a class="header-anchor" href="#数据流"><span>数据流</span></a></h4><ul><li>状态管理 ：Vuex 统一管理 graphData （cells 数据）</li><li>核心画布 ： ladderArea.vue 初始化 AntV X6 画布，集成拖拽（DnD）、选择、历史、键盘等插件</li><li>功能块定义 ： dataJson/ 下按分类存放 JSON 格式的功能块元数据</li></ul><h4 id="构建" tabindex="-1"><a class="header-anchor" href="#构建"><span>构建</span></a></h4><ul><li>输出为 UMD 库 （library name: Modal ），每个入口独立打包</li><li>开发服务器端口 9527 ，支持热重载</li><li>当前 webpack.config.js 只打包 ld 入口， fbd 入口被注释</li></ul><h2 id="项目二描述" tabindex="-1"><a class="header-anchor" href="#项目二描述"><span>项目二描述</span></a></h2><p>这是一套工业控制器 Web 组态工具——Vue 3 可视化拖拽配置工业协议设备，REST API 下发到控制器固件，并集成 VSCode Web IDE 实现完整的组态-编程-调试工作流。</p><h3 id="技术栈2" tabindex="-1"><a class="header-anchor" href="#技术栈2"><span>技术栈2</span></a></h3><ul><li>Vue 3.4 + TypeScript + Vite 4</li><li>Element Plus UI 库 + Pinia （持久化）+ Vue Router 4（动态路由）</li><li>ECharts 5（仪表盘）、CodeMirror 6（脚本编辑）、vue-i18n（中英文）</li><li>Axios 类封装（全屏 loading、401/403 拦截、错误处理）</li><li>RSA 加密登录（jsencrypt）</li></ul><h2 id="项目三描述" tabindex="-1"><a class="header-anchor" href="#项目三描述"><span>项目三描述</span></a></h2><p>为 code-server（Web 版 VSCode）定制的 IEC 61131-3 结构化文本（ST）语言 + LD 梯形图 PLC 编程插件 ，是 eCON 逻辑编程 IDE（fcs-ide，嵌入 9888 端口）的核心扩展。</p><p>基于微软官方 LSP 示例（lsp-sample）和 Custom Editor 示例（catScratch）二次开发。</p>',23)])])}const p=a(s,[["render",t]]),c=JSON.parse('{"path":"/%E9%A1%B9%E7%9B%AE.html","title":"项目","lang":"en-US","frontmatter":{},"headers":[{"level":2,"title":"项目一描述","slug":"项目一描述","link":"#项目一描述","children":[{"level":3,"title":"技术栈","slug":"技术栈","link":"#技术栈","children":[]},{"level":3,"title":"项目结构","slug":"项目结构","link":"#项目结构","children":[]},{"level":3,"title":"核心功能","slug":"核心功能","link":"#核心功能","children":[]}]},{"level":2,"title":"项目二描述","slug":"项目二描述","link":"#项目二描述","children":[{"level":3,"title":"技术栈2","slug":"技术栈2","link":"#技术栈2","children":[]}]},{"level":2,"title":"项目三描述","slug":"项目三描述","link":"#项目三描述","children":[]}],"git":{"updatedTime":1794894347000,"contributors":[{"name":"yuanwenjuan","username":"","email":"yuanwenjuan@supconit","commits":1}],"changelog":[{"hash":"0582caee118f8c73ab7de9174eacb637daadda43","time":1794894347000,"email":"yuanwenjuan@supconit","author":"yuanwenjuan","message":"feat init"}]},"filePathRelative":"项目.md","excerpt":"\\n<h2>项目一描述</h2>\\n<p>一个工业 PLC 编程的 梯形图（LD）和功能块图（FBD）图形化编辑工具 ，用于以拖拽方式替代传统文本化的 PLC 编程。</p>\\n<h3>技术栈</h3>\\n<p>Vue 2 (^2.6.14) + Vuex 3 + Composition API</p>\\n<p>AntV X6 (^2.9.4) — 核心画布引擎</p>\\n<p>Element UI 2</p>\\n<p>webpack</p>\\n<h3>项目结构</h3>\\n<p>ldfbd/\\n├── src/\\n│   ├── index.js          # 组件库入口（Vue 插件）\\n│   ├── ld.js             # 梯形图模式入口\\n│   ├── fbd.js            # 功能块图模式入口\\n│   ├── src/\\n│   │   ├── LD.vue / FBD.vue   # 两种模式的容器组件\\n│   │   ├── ladderArea.vue     # ⭐ 核心编辑画布（213KB+，核心组件）\\n│   │   ├── components/        # 子组件（工具栏、功能块节点、变量管理等）\\n│   │   ├── store/modules/     # Vuex 状态（主要管理 cells 数据）\\n│   │   ├── utils/             # 工具函数（20+ 个文件：坐标、连线、删除、撤销等）\\n│   │   ├── dataJson/          # 功能块元数据 JSON（按 LD/FBD 分类，各 11 类）\\n│   │   └── api/ld.js          # 后端 API 接口\\n│   ├── assets/\\n│   │   ├── images/            # 梯形图元件图片（触点、线圈、定时器等）\\n│   │   └── svg/               # 图标\\n│   └── index.html\\n├── webpack.config.js     # Webpack 构建配置（UMD 库打包）\\n└── vue.config.js         # Vue CLI 后备配置</p>"}');export{p as comp,c as data};
